// audio.c - voices on the SPU, the jukebox as XA-ADPCM streams read straight off the disc.
#include "audio.h"
#include <psxspu.h>
#include <psxcd.h>
#include <hwregs_c.h>
#include "songs.inc"     // GENERATED by tools/build_audio.py: the song table (file, channel, name, artist, seconds)

extern const u8 voices_bin[];
extern const u32 voices_bin_size;

// ---- voices ----
#define ALLOC_START 0x1010
static int voice_addr[VOICE_N], voice_rate[VOICE_N];
static int next_ch = 0;
static int spu_ok;

static int upload_sample(const void *data, int size) {
    static int next = ALLOC_START;
    int addr = next;
    size = (size + 63) & ~63;
    SpuSetTransferMode(SPU_TRANSFER_BY_DMA);
    SpuSetTransferStartAddr(addr);
    SpuWrite((const u32 *)data, size);
    SpuIsTransferCompleted(SPU_TRANSFER_WAIT);
    next = addr + size;
    return addr;
}

void audio_voice(int v) {
    if (!spu_ok || v < 0 || v >= VOICE_N || !voice_addr[v]) return;
    int ch = next_ch;
    SpuSetKey(0, 1 << ch);
    SPU_CH_FREQ(ch) = getSPUSampleRate(voice_rate[v]);
    SPU_CH_ADDR(ch) = getSPUAddr(voice_addr[v]);
    SPU_CH_VOL_L(ch) = 0x2fff;
    SPU_CH_VOL_R(ch) = 0x2fff;
    SPU_CH_ADSR1(ch) = 0x00ff;
    SPU_CH_ADSR2(ch) = 0x0000;
    SpuSetKey(1, 1 << ch);
    next_ch = (ch + 1) % 8;
}

// ---- jukebox ----
#define SONG_FILES 8
static CdlLOC file_loc[SONG_FILES];
static int file_ok[SONG_FILES];
static int cd_ok;
static int cur_song = -1, shuffle = 1;
static volatile int song_done;
static volatile int sectors_played;
static CdlFILTER filter;

typedef struct { u8 file, channel, submode, coding; } XAHeader;
typedef struct { CdlLOC pos; XAHeader xa[2]; u8 data[2048]; u32 edc; u8 ecc[276]; } Sector;
static Sector sector;

static void cd_ready(CdlIntrResult event, u8 *payload) {
    (void)payload;
    if (event != CdlDataReady) return;
    CdGetSector(&sector, sizeof(Sector) / 4);
    if (!(sector.xa[0].submode & (1 << 2))) { song_done = 1; return; }    // not audio any more: the song ran out
    sectors_played++;
    if (sector.xa[0].submode & 0x80) song_done = 1;                      // end of file
}

int audio_song_count(void) { return NSONGS; }
const char *audio_song_name(int i) { return songs[i].name; }
const char *audio_song_artist(int i) { return songs[i].artist; }
int audio_song_len(int i) { return songs[i].seconds; }
int audio_jukebox_current(void) { return cur_song; }
static int play_frames;                                                   // audio sectors go straight to the decoder (no callback), so time by the frame
int audio_jukebox_elapsed(void) { return play_frames / 60; }
void audio_jukebox_toggle_shuffle(void) { shuffle ^= 1; }
int audio_jukebox_shuffle(void) { return shuffle; }
int audio_cd_ok(void) { return cd_ok; }

void audio_jukebox_stop(void) {
    if (!cd_ok) return;
    if (cur_song >= 0) CdControl(CdlPause, 0, 0);
    cur_song = -1; song_done = 0;
}
void audio_jukebox_play(int i) {
    if (!cd_ok || i < 0 || i >= NSONGS) return;
    if (!file_ok[songs[i].file]) return;
    CdControl(CdlPause, 0, 0);
    filter.file = 1; filter.chan = songs[i].channel;
    CdControl(CdlSetfilter, &filter, 0);
    int mode = (XA_RATE == 37800 ? CdlModeSpeed : 0) | CdlModeRT | CdlModeSF;   // 8 songs interleaved: 2x speed at 37.8 kHz, 1x at 18.9 kHz
    CdControl(CdlSetmode, &mode, 0);
    sectors_played = 0; song_done = 0; cur_song = i; play_frames = 0;
    CdControl(CdlReadS, &file_loc[songs[i].file], 0);
}
void audio_jukebox_next(void) {
    if (NSONGS == 0) return;
    int n = shuffle ? (int)(rand() % NSONGS) : (cur_song + 1) % NSONGS;
    if (shuffle && n == cur_song) n = (n + 1) % NSONGS;
    audio_jukebox_play(n);
}
void audio_update(void) {
    if (cur_song >= 0) play_frames++;
    if (cur_song >= 0 && song_done) { song_done = 0; audio_jukebox_next(); }
    if (cur_song >= 0 && play_frames > (songs[cur_song].seconds + 4) * 60) audio_jukebox_next();   // a safety net if the end never comes
}

void audio_init(void) {
    SpuInit();
    spu_ok = 1;
    // the voice blob: u32 count, then {u32 offset, u32 size, u32 rate} per clip, then the ADPCM data
    const u32 *hdr = (const u32 *)voices_bin;
    int n = (int)hdr[0];
    for (int i = 0; i < VOICE_N && i < n; i++) {
        u32 off = hdr[1 + i * 3], size = hdr[2 + i * 3], rate = hdr[3 + i * 3];
        voice_addr[i] = upload_sample(voices_bin + off, (int)size);
        voice_rate[i] = (int)rate;
    }
    // the disc
    cd_ok = 0;
    if (CdInit()) {
        CdlFILE f; char name[32];
        int any = 0;
        for (int i = 0; i < SONG_FILES; i++) {
            sprintf(name, "\\MUSIC%d.XA;1", i);
            file_ok[i] = CdSearchFile(&f, name) != 0;
            if (file_ok[i]) { file_loc[i] = f.pos; any = 1; }
        }
        if (any) { cd_ok = 1; CdReadyCallback(&cd_ready); }
    }
    SpuSetCommonMasterVolume(0x3fff, 0x3fff);
    SPU_CD_VOL_L = 0x3fff; SPU_CD_VOL_R = 0x3fff;
}
